        dismissed: false, stale: false, submitted_at: "2026-10-13T00:00:00Z" },
      { id: 6, user: { id: 45, login: "robot", type: "Bot" }, state: "APPROVED", commit_id: head,
        dismissed: false, stale: false, submitted_at: "2026-10-13T00:00:00Z" },
      { id: 7, user: { id: 46, login: "observer", type: "User" }, state: "PENDING", commit_id: "",
        dismissed: false, stale: false, submitted_at: "2026-10-13T00:00:00Z" }
    ]],
    [`GET /api/v1/repos/team/project/commits/${head}/status?limit=100&page=1`,
      { sha: head, statuses: [{ context: "build", status: "success" }, { context: "advisory", status: "failure" }], total_count: 2 }],
    ["GET /api/v1/repos/team/project/pulls?state=all&limit=100&page=1", [{ ...pr, ...overrides }]],
    ["POST /api/v1/repos/team/project/pulls/7/merge", null]
  ]);
  const adapter = new GiteaPullRequestAdapter({ instanceId: "gitea", baseUrl: "https://forge.example/",
    owner: "team", name: "project", token: async () => "secret", fetcher: async (input, init) => {
      const url = new URL(String(input));
      const method = init?.method ?? "GET";
      calls.push({ method, path: url.pathname + url.search,
        ...(init?.body ? { body: JSON.parse(String(init.body)) as unknown } : {}) });
      const key = `${method} ${url.pathname}${url.search}`;
      return new Response(routes.has(key) ? JSON.stringify(routes.get(key)) : "", {
